def main(argv=None):
    """Job entry point (design plan section 5.1, T1). Parameters: none."""
    #spark = (SparkSession
    #         .builder
    #         .appName('recommendation_system')
    #         .config('spark.driver.memory', '63g')
    #         .config('spark.executor.cores', '5')
    #         .config('spark.executor.instances', '14')
    #         .config('spark.executor.memory', '125g')
    #         .config('spark.dynamicAllocation.enabled', 'false')
    #         .config('spark.debug.maxToStringFields', "100")
    #         .config('spark.sql.crossJoin.enabled', "true")
    #         .config('spark.driver.memoryOverhead', '8192')
